old_string:
// Idempotency: use detected_at truncated to UTC day so the unique constraint
// (product_external_id, variant_external_id, detected_at) enforces one batch per day per item.
const now = new Date();
// Truncate to UTC day start so same-day events resolve to the same timestamp for dedup
const detectedAt = new Date(now);
detectedAt.setUTCHours(0, 0, 0, 0);

new_string:
// Use the actual restock detection timestamp from the webhook payload
const now = new Date();
const detectedAt = updatedAt ? new Date(updatedAt) : now;
